function seedWorkspace(name, alternate = false) {
 const titles = alternate ? ['仓库消防设施检查','第三季度整改汇总'] : ['二车间设备异常排查','本周安全生产报告','制定明日巡检计划','SOP 作业流程复核','分析 3 号泵运行趋势'];
 return {name, current:null, sessions:titles.map((title,i)=>({id:uid(),title,pinned:i===0,messages:[{role:'user',text:title},{role:'assistant',text:'已整理当前工作区的相关资料。你可以查看下面的示例结果，或者继续告诉我想深入了解的内容。',kind:i===1?'report':'analysis'}]})),todos:[{id:uid(),text:alternate?'复核仓库消防设施':'复核 3 号泵温度异常',date:BASE_DATE,done:false},{id:uid(),text:'确认明日巡检人员安排',date:'2026-09-14',done:false},{id:uid(),text:'检查报告归档',date:BASE_DATE,done:true}],events:[{id:uid(),title:'安全生产例会',date:BASE_DATE,time:'09:30',place:'一号会议室'},{id:uid(),title:'二车间现场巡检',date:BASE_DATE,time:'14:00',place:alternate?'东侧仓库':'二车间'}],files:[{id:uid(),name:'安全生产管理制度.pdf',size:'2.4 MB',type:'PDF',sample:true},{id:uid(),name:'本周设备运行数据.xlsx',size:'856 KB',type:'XLSX',sample:true},{id:uid(),name:'车间巡检记录.docx',size:'1.2 MB',type:'DOCX',sample:true}],project:alternate?'仓库安全管理':'安全生产日常管理'};
}
function initial() {return {version:1,workspace:'w1',workspaces:{w1:seedWorkspace('华东工厂 · 主工作区'),w2:seedWorkspace('东侧仓库 · 协作空间',true)},settings:{theme:'light',compact:false,enterSend:true,model:models[0]},enabled:{},recent:['设备监测','安全检查','SOP 检测','全景 VR'],rememberUser:null};}
let state;
try { const data=JSON.parse(localStorage.getItem(STORE)); state=data?.version===1&&data.workspaces?.[data.workspace]?data:initial(); } catch {state=initial();}
let user;
try{user=JSON.parse(sessionStorage.getItem('yuvi-user')) || state.rememberUser;}catch{user=state.rememberUser;}
const ui={left:innerWidth>700,right:innerWidth>960,tab:'workspace',mode:'chat',draft:'',attachments:[],thinking:false,pending:null,calendar:'2026-09',day:BASE_DATE,fileTarget:'chat'};
const viewportMode=()=>innerWidth<=700?'mobile':innerWidth<=960?'tablet':'desktop';
let layoutMode=viewportMode();
const panelPreferences={desktop:{left:true,right:true},tablet:{left:true,right:false}};
function syncPanelDom(){
 const mobile=viewportMode()==='mobile';
 if(mobile&&ui.left&&ui.right)ui.left=false;
 for(const [key,selector] of [['left','.sidebar'],['right','.right-panel']]){
  const panel=$(selector),toggle=$(`[data-action="toggle-${key}"]`);
  if(!panel||!toggle)continue;
  if(!ui[key]&&panel.contains(document.activeElement))toggle.focus();
  panel.classList.toggle('hidden',!ui[key]);panel.toggleAttribute('inert',!ui[key]);
  toggle.setAttribute('aria-expanded',String(ui[key]));
  const label=(ui[key]?'收起':'展开')+(key==='left'?'左侧导航':'右侧面板');
  toggle.setAttribute('aria-label',label);toggle.title=label;
 }
 $('.mobile-overlay')?.classList.toggle('active',innerWidth<=960&&(ui.right||(mobile&&ui.left)));
}
let viewportFrame;
function updateViewport(){
 cancelAnimationFrame(viewportFrame);
 viewportFrame=requestAnimationFrame(()=>{
  const viewport=window.visualViewport;
  const height=viewport&&viewport.scale===1?viewport.height:innerHeight;
  document.documentElement.style.setProperty('--viewport-height',`${Math.round(height)}px`);
  const mode=viewportMode();
  if(mode!==layoutMode){
   if(layoutMode!=='mobile')panelPreferences[layoutMode]={left:ui.left,right:ui.right};
   const next=mode==='mobile'?{left:false,right:false}:panelPreferences[mode];
   ui.left=next.left;ui.right=mode==='tablet'?false:next.right;layoutMode=mode;
  }
  syncPanelDom();
 });
}
window.addEventListener('resize',updateViewport);
window.visualViewport?.addEventListener('resize',updateViewport);
updateViewport();
