function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function openModal(title,body,wide=false){const d=$('#modal');d.classList.toggle('wide',wide);d.innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2>${ib('close','关闭弹窗','close-modal')}</div><div class="modal-body">${body}</div>`;if(!d.open)d.showModal();}
function closeModal(){$('#modal').close();}
